using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 Label journeyHud,weatherHud;
 void JourneyAction(string action){if(CoopClient)return;if(action=="cancel"){game.Change(()=>game.EndJourney("Turned back / expedition abandoned."));return;}if(int.TryParse(action,out int i)&&dungeon==null)game.BeginJourney(i);}
 void ShowJourneyPlanner(){var b=Panel("EXPEDITIONS / PREPARE, SCAVENGE, COME HOME");coopMenu="journeys";menu.Position=new(80,30);menu.Size=new(1120,650);var j=game.Life.Journey;Text(b,game.Forecast+"\n"+(j?.Outcome??"No expedition planned.")+"\nF5 opens this planner. G throws a stone distraction (one stone). Refusing a trip has no penalty.");
  if(j?.Active==true&&j.Seed==game.Save.Seed){var at=ExpeditionContentSite.Place(game.World,j.Site);Text(b,$"DESTINATION / {ExpeditionContentSite.All[j.Site].Name}\n{(j.Reached?"RETURN HOME":"OUTBOUND")} / destination {ExpeditionGame.Distance(player.Position.X,player.Position.Z,at.X,at.Z):0}m / home {ExpeditionGame.Distance(player.Position.X,player.Position.Z,j.HomeX,j.HomeZ):0}m\n"+game.JourneyChecklist(j.Site));LocationButton(b,ExpeditionContentSite.All[j.Site].Name,at.X,at.Z,ShowJourneyPlanner);LocationButton(b,"Expedition refuge",j.HomeX,j.HomeZ,ShowJourneyPlanner);Button(b,"ABANDON PLAN / KEEP YOUR SUPPLIES",()=>{if(!CoopRequest("journey","cancel"))JourneyAction("cancel");ShowJourneyPlanner();});}
  else{Text(b,game.JourneyRefuge(game.Save.X,game.Save.Z)?"You are at a departure refuge. Select a destination; the plan does not teleport or consume supplies.":"Return to the trailhead, a bag, your camp or a friendly settlement to begin a planned expedition.");var scroll=new ScrollContainer{CustomMinimumSize=new(1000,320)};b.AddChild(scroll);var list=new VBoxContainer{CustomMinimumSize=new(970,0)};scroll.AddChild(list);
   foreach(int i in Enumerable.Range(0,ExpeditionContentSite.All.Length).OrderBy(i=>{var p=ExpeditionContentSite.Place(game.World,i);return ExpeditionGame.Distance(player.Position.X,player.Position.Z,p.X,p.Z);})){int site=i;var d=ExpeditionContentSite.All[i];var state=game.World.Changes.FieldSites.FirstOrDefault(s=>s.Index==i);var at=ExpeditionContentSite.Place(game.World,i);Text(list,$"T{d.Tier} / {d.Name} / {ExpeditionGame.Distance(at.X,at.Z,player.Position.X,player.Position.Z):0}m / {(state?.Seen==true?"DISCOVERED":"RUMOURED LOCATION")}\n"+(HasFieldLocker(i)?LockerContents(i):d.Mode=="rest"?"Sheltered rest and a small fire":"Provisions and local salvage")+(state?.LockerOpened==true?" / SPECIALIST LOCKER EMPTY":""));Button(list,"PLAN / "+d.Name,()=>ShowJourneyDestination(site));}
  }foreach(var entry in game.Life.JourneyLog.TakeLast(3))Text(b,entry);Button(b,"BACK TO WORLD",CloseMenu);
 }
 void ShowJourneyDestination(int i){var b=Panel(ExpeditionContentSite.All[i].Name.ToUpperInvariant()+" / DEPARTURE CHECK");Text(b,game.JourneyChecklist(i));var at=ExpeditionContentSite.Place(game.World,i);LocationButton(b,ExpeditionContentSite.All[i].Name,at.X,at.Z,()=>ShowJourneyDestination(i));Text(b,"Estimated travel assumes walking and detours. Combat, slopes, searching and resting take extra time. You can turn back without losing equipment or levels. Specialist caches are finite in each world.");Button(b,"SET OUT / TRACK THIS DESTINATION",()=>{if(!CoopRequest("journey",i.ToString()))JourneyAction(i.ToString());ShowJourneyPlanner();});Button(b,"CHOOSE ANOTHER DESTINATION",ShowJourneyPlanner);}
 void DrawJourneyHud(){if(!JourneyEnabled)return;if(journeyHud==null){journeyHud=HudLabel(11);weatherHud=HudLabel(11);}weatherHud.Position=new(34,275);weatherHud.Text=game.Forecast+(game.WeatherSheltered?" / UNDER COVER":"")+(game.Life.Wetness>40?$" / WET {game.Life.Wetness:0}%":"")+(game.Life.Chill>40?$" / COLD {game.Life.Chill:0}%":"");journeyHud.Position=new(34,305);var j=game.Life.Journey;journeyHud.Text="";if(j?.Active==true&&j.Seed==game.Save.Seed){var at=ExpeditionContentSite.Place(game.World,j.Site);double x=j.Reached?j.HomeX:at.X,z=j.Reached?j.HomeZ:at.Z;string direction=x>player.Position.X?"E":"W";direction=(z>player.Position.Z?"S":"N")+direction;journeyHud.Text=$"{(j.Reached?"RETURN TO REFUGE":ExpeditionContentSite.All[j.Site].Name.ToUpperInvariant())} / {ExpeditionGame.Distance(player.Position.X,player.Position.Z,x,z):0}m {direction} / F5";}var searching=game.World.Changes.FieldSites.FirstOrDefault(s=>s.SearchRemaining>0&&s.SearchOwner==game.Life.SoulOwner);if(searching!=null)journeyHud.Text+=$"\nOPENING SHUTTER / {searching.SearchRemaining:0}s / stay close";}
}
